package comtrya

// String set mirroring the WIT `check-state` variant exposed by
// ext_checks. Adding a state on either side requires adding it on
// the other.
#CheckState: "pending" | "running" | "succeeded" | "failed" | "skipped"

// A single named check the Project expects results for. The
// catalog is informational — ext_checks records runs as they
// arrive — but declaring it lets the kernel surface
// "expected check is missing" without depending on a particular CI.
//
// PR gating lives on `pulls.requiredChecks` (ext_pull_requests);
// `required` here marks a check as required at the *catalog* level
// so other extensions can read a single source of truth.
#Check: {
  name:         string
  displayName?: string
  description?: string
  required?:    bool | *false
}

#ChecksPolicy: {
  catalog?: [string]: #Check
}

#Project: { checks?: #ChecksPolicy }
